import React from 'react';
import { Loader2, Image as ImageIcon } from 'lucide-react';
import type { WidgetProps } from '../types';
import { useWidgetFetch } from '../hooks/useWidgetFetch';

interface ImagePayload {
  url: string;
  title?: string;
}

const StaticImageWidget: React.FC<WidgetProps> = ({ definition, period }) => {
  const { data, loading, error } = useWidgetFetch<ImagePayload>(
    definition.widget_id,
    period,
    definition.refresh_policy,
    definition.field_mapping?.rename
  );

  if (loading) {
    return (
      <div className="w-full h-full flex items-center justify-center">
        <Loader2 className="w-6 h-6 text-blue-500 animate-spin" />
      </div>
    );
  }

  if (error || !data?.url) {
    return (
      <div className="w-full h-full flex flex-col items-center justify-center text-gray-400 p-4">
        <ImageIcon className="w-8 h-8 mb-2 opacity-50" />
        <span className="text-sm text-center">Imagen no disponible</span>
      </div>
    );
  }

  return (
    <div className="w-full h-full p-0 m-0 overflow-hidden relative group">
      <img
        src={data.url}
        alt={definition.nombre}
        className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105"
      />
      <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/60 to-transparent p-3">
        <p className="text-white text-xs font-medium truncate">{definition.descripcion}</p>
      </div>
    </div>
  );
};

export default StaticImageWidget;
